namespace MediaExport.Core.Media.Models;

/// <summary>A video height the media really has, with the rough size of a download at that height.</summary>
public sealed record VideoQuality(int Height, long? ApproximateBytes);

/// <param name="IsAutomatic">Generated by the site's speech recognition rather than written by someone.</param>
public sealed record SubtitleTrack(string Language, string Name, bool IsAutomatic);

public sealed record Chapter(TimeSpan Start, TimeSpan End, string Title);

/// <summary>What can be exported from a piece of media (read once, when it's chosen), or why nothing can.</summary>
public sealed record MediaDetails(
    string? Problem,
    IReadOnlyList<VideoQuality> VideoQualities,
    long? AudioBytes,
    IReadOnlyList<SubtitleTrack> Subtitles,
    IReadOnlyList<Chapter> Chapters,
    bool SupportsSponsorBlock)
{
    public bool IsExportable => Problem is null;
    public bool HasVideo => VideoQualities.Count > 0;

    public static MediaDetails Unavailable(string problem) => new(problem, [], null, [], [], false);
}
